export const PATHWAY_BY_MODULE_ID = new Map(PATHWAY_MODULES.map((m) => [m.id, m]))
export const PATHWAY_BY_CHAPTER_ID = new Map(PATHWAY_MODULES.flatMap((m) => m.subchapters.map((s) => [s.id, { module: m, sub: s }])))

export function pathwayLabel(moduleOrder: number, sub: PathwaySubChapter): string {
  return `${moduleOrder}.U${sub.unitIndex}.${sub.role} · ${sub.title}`
}

export function unitsForModule(module: PathwayModule) {
  const map = new Map<number, { unitIndex: number; unitTitle: string; unitGrammar: string; chapters: PathwaySubChapter[] }>()
  for (const sub of module.subchapters) {
    let unit = map.get(sub.unitIndex)
    if (!unit) { unit = { unitIndex: sub.unitIndex, unitTitle: sub.unitTitle, unitGrammar: sub.unitGrammar, chapters: [] }; map.set(sub.unitIndex, unit) }
    unit.chapters.push(sub)
  }
  return [...map.values()].sort((a, b) => a.unitIndex - b.unitIndex)
}

export function mergePathwayChapters<C extends { id: string; module_id: string; title: string; description: string; order_index: number; lesson_content: unknown }>(chapters: C[]): C[] {
  const byId = new Map(chapters.map((c) => [c.id, c]))
  const pathwayIds = new Set(PATHWAY_MODULES.flatMap((m) => m.subchapters.map((s) => s.id)))
  const other = chapters.filter((c) => !pathwayIds.has(c.id) && !PATHWAY_BY_MODULE_ID.has(c.module_id))
  const rebuilt: C[] = []
  for (const mod of PATHWAY_MODULES) {
    for (const sub of mod.subchapters) {
      const existing = byId.get(sub.id)
      rebuilt.push({ ...(existing ?? {} as C), id: sub.id, module_id: mod.id, title: sub.title, description: sub.description, order_index: sub.orderIndex, lesson_content: existing?.lesson_content ?? {} } as C)
    }
  }
  return [...rebuilt, ...other]
}

export function applyPathwayModuleMeta<M extends { id: string; title: string; description: string; cefr_level: string; order_index: number }>(modules: M[]): M[] {
  return PATHWAY_MODULES.map((pm) => {
    const existing = modules.find((m) => m.id === pm.id || m.order_index === pm.orderIndex)
    return { ...(existing ?? { id: pm.id } as M), id: pm.id, title: pm.title, description: pm.description, cefr_level: pm.cefr, order_index: pm.orderIndex }
  })
}

export function playableChapterIds(hasContent: (id: string) => boolean): string[] {
  return PATHWAY_MODULES.flatMap((m) => m.subchapters.map((s) => s.id)).filter(hasContent)
}

